                case "正常":
                    statusDisplay = "✅ 正常";
                    break;
                case "会员":
                    statusDisplay = " 会员";
                    break;
                case "封禁":
                    statusDisplay = "🚫 封禁";
                    break;
                default:
                    statusDisplay = userInfo.status;
            }

            var keyValue = userInfo.api_key || "";
            var maskedKey = "";
            if (keyValue.length > 10) {
                maskedKey = keyValue.substring(0, 3) + "****" + keyValue.substring(keyValue.length - 4);
            } else {
                maskedKey = "****" + keyValue.substring(keyValue.length - 4);
            }

            var email = userInfo.email || "未绑定";
            var maskedEmail = "未绑定";
